function r(t){let n=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),a=String(t.getDate()).padStart(2,"0");return`${n}-${e}-${a}`}function c(t){if(t.selectedPeriod==="all")return{startDate:"",endDate:""};let n=new Date;switch(t.selectedPeriod){case"monthly":{let e=parseInt(t.selectedMonth,10),a=parseInt(t.selectedYear,10);if(Number.isNaN(e)||Number.isNaN(a))return{startDate:"",endDate:""};let s=new Date(a,e,1),o=new Date(a,e+1,0);return{startDate:r(s),endDate:r(o)}}case"yearly":{let e=n.getFullYear(),a=new Date(e,0,1),s=new Date(e,11,31);return{startDate:r(a),endDate:r(s)}}case"last30":{let e=new Date(n);return e.setDate(n.getDate()-30),{startDate:r(e),endDate:r(n)}}case"last7":{let e=new Date(n);return e.setDate(n.getDate()-7),{startDate:r(e),endDate:r(n)}}case"custom":return{startDate:t.customStartDate||"",endDate:t.customEndDate||""};case"monthOnly":{if(t.selectedMonthOnly&&t.selectedYearOnly){if(t.customStartDate&&t.customEndDate)return{startDate:t.customStartDate,endDate:t.customEndDate};let e=parseInt(t.selectedMonthOnly,10),a=parseInt(t.selectedYearOnly,10),s=new Date(a,e,1),o=new Date(a,e+1,0);return{startDate:r(s),endDate:r(o)}}return{startDate:"",endDate:""}}default:return t.customStartDate||t.customEndDate?{startDate:t.customStartDate||"",endDate:t.customEndDate||""}:{startDate:"",endDate:""}}}function D(t){switch(t){case"all":return"all";case"thisMonth":return"monthly";case"thisYear":return"yearly";case"last30":return"last30";case"last7":return"last7";case"thisQuarter":case"lastYear":case"custom":return"custom";default:return"custom"}}function u(t){if(t.selectedDatePreset)return t.selectedDatePreset;switch(t.selectedPeriod){case"all":return"all";case"monthly":return"thisMonth";case"yearly":return"thisYear";case"last30":return"last30";case"last7":return"last7";default:return"custom"}}export{r as a,c as b,D as c,u as d};
